import {openDialog,closeDialog,ownsDialog,environment,jsonRequest} from './ui-core.mjs';
import {integrationsPage,bindIntegrations,clearIntegrationsSession} from './integration-ui.mjs';
import {codingPage,bindCoding,clearCodingSession} from './coding-ui.mjs';
import {usagePage,bindUsage,clearUsageSession} from './usage-ui.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null?'—':'¥'+Number(n).toFixed(4),percent=n=>(Number(n||0)*100).toFixed(1)+'%';
const labels={running:'运行中',success:'已完成',stopped:'已停止',approval:'待审批',failed:'失败'},actions={stop:'自动停止',degrade:'降级模型',approve:'人工确认'};
const nav=[['overview','◫','运行总览'],['runs','↗','任务追踪'],['alerts','◉','风险与审批'],['coding','⌁','编码工具'],['usage','▥','用量历史'],['cost','▥','成本分析'],['policies','☷','费用策略'],['integrations','⊞','接入中心'],['deploy','⌘','私有部署']];
let session=null,epoch=0,detailEpoch=0,current='overview';
let runFilters={q:'',status:'',customer:'',feature:'',offset:0},alertFilters={status:'',offset:0};
const pending=new Set();
const title=(h,p,b='')=>`<div class="heading"><div><h1>${h}</h1><p>${p}</p></div><div class="actions">${b}</div></div>`;
const refresh='<button class="button" data-console-refresh>刷新</button>';
function shell(){current=location.hash.slice(1)||'overview';if(!nav.some(n=>n[0]===current))current='overview';$('#breadcrumb').textContent=nav.find(n=>n[0]===current)[2];$('#nav').innerHTML=nav.map(([id,symbol,name])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}><span class="nav-icon">${symbol}</span>${name}</a>`).join('');const b=$('[data-console-logout]');if(b){b.hidden=!session;b.onclick=logout}const role=$('#console-role');if(role)role.textContent=session?(session.canManage?'管理员 · 当前页面会话':'只读 · 当前页面会话'):'未验证权限';environment(session?(session.canManage?'真实服务 · 管理员':'真实服务 · 只读'):'尚未连接',session?'同源服务 · 不混入演练数据':'连接本机服务后读取真实数据')}
function logout(){session=null;epoch++;detailEpoch++;clearCodingSession();clearUsageSession();clearIntegrationsSession();runFilters={q:'',status:'',customer:'',feature:'',offset:0};alertFilters={status:'',offset:0};closeDialog();show()}
function api(path,method='GET',data){if(!session)return Promise.reject(Error('请先连接服务'));return jsonRequest(path,{method,headers:{authorization:'Bearer '+session.key,'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store'},'此网址没有可用的 AgentGuard API。请在本机执行 npm run start:local，并打开该服务地址。未加载演练数据。')}
function show(){const ticket=++epoch;shell();const app=$('#app');if(current==='deploy'){app.innerHTML=deployment();return}if(!session){app.innerHTML=title('连接 AgentGuard','使用同源服务的访问密钥，统一读取任务、用量和接入配置。')+'<section class="card console-login-card"><h2>连接你的服务</h2><p>ADMIN_KEY 可管理，READ_KEY 仅查看。凭证只在本页面内存中保留，刷新页面后需重新输入。</p><form id="console-login"><label>访问密钥<input name="key" type="password" autocomplete="off" required placeholder="ADMIN_KEY 或 READ_KEY"></label><button class="button primary" type="submit">连接服务</button></form><div id="console-message" role="status"></div><p class="usage-caption">尚未连接时不显示样例统计。首次使用请查看 <a href="#deploy">本机运行步骤</a>。</p></section>';const f=$('#console-login');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');if(b.disabled)return;b.disabled=true;try{const key=String(new FormData(f).get('key')||'').trim();if(!key)throw Error('请输入访问密钥');const d=await jsonRequest('/api/session',{headers:{authorization:'Bearer '+key},cache:'no-store'},'此网址没有可用 API。请从本机启动的 AgentGuard 服务地址打开。');if(ticket!==epoch||!f.isConnected)return;if(!['admin','read'].includes(d.role))throw Error('服务返回了无效的权限信息');if(d.storageReady===false)throw Error('服务端存储尚未就绪，请修复 SQLite 配置后重试');session={key,role:d.role,canManage:d.canManage===true&&d.role==='admin'};show()}catch(err){if(ticket===epoch&&f.isConnected)$('#console-message').textContent=err.message}finally{b.disabled=false}};return}const shared={...session,onLogout:logout};if(current==='coding'){app.innerHTML=codingPage();bindCoding(shared);return}if(current==='usage'){app.innerHTML=usagePage();bindUsage(shared);return}if(current==='integrations'){app.innerHTML=integrationsPage();bindIntegrations(shared);return}app.innerHTML='<section id="console-root"><div id="console-content"><div class="card empty">正在读取真实服务数据…</div></div><div id="console-message" role="status"></div></section>';loadPage(ticket)}
async function loadPage(ticket){const root=$('#console-root'),page=current;const endpoint={overview:'/api/overview',runs:'/api/tasks?'+new URLSearchParams({...runFilters,limit:50}),alerts:'/api/alerts?'+new URLSearchParams({...alertFilters,limit:50}),cost:'/api/costs',policies:'/api/policies'}[page];try{const d=await api(endpoint);if(ticket!==epoch||!root.isConnected)return;$('#console-content').innerHTML=({overview:overview,runs:runs,alerts:alerts,cost:cost,policies:policies})[page](d);bindPage(root,page,d,ticket)}catch(err){if(ticket!==epoch||!root.isConnected)return;$('#console-content').innerHTML=title(nav.find(n=>n[0]===page)[2],'读取真实服务数据失败。',refresh)+'<div class="card empty">未能读取数据。请检查同源服务与访问权限后重试；没有切换为演练。</div>';$('#console-message').textContent=err.message;bindRefresh(root)}}
function bindRefresh(root){root.querySelector('[data-console-refresh]')?.addEventListener('click',show)}
function stat(label,value,note){return `<div class="card stat"><div class="label">${label}</div><div class="value">${value}</div><small>${note}</small></div>`}
function stats(m={}){return '<div class="stats">'+stat('已知任务成本',money(m.cost||0),'包含失败调用和重试，未计价费用不视为免费')+stat('成功任务率',m.completed?percent(m.rate):'—',`${Number(m.success||0)} 成功 / ${Number(m.completed||0)} 已结束`)+stat('每个成功任务成本',money(m.unit),'全部已知任务成本 ÷ 成功任务数')+stat('已结束任务',Number(m.completed||0),'完成、失败、停止计入分母；运行及待审批不计入')+'</div>'}
function taskTable(ts){return '<div class="table-wrap"><table><thead><tr><th>任务 / ID</th><th>客户 / 功能</th><th>策略 / 模型</th><th>成本 / 预算</th><th>状态</th><th></th></tr></thead><tbody id="real-task-rows">'+ts.map(t=>`<tr><td><strong>${esc(t.name||t.id)}</strong><small>${esc(t.id)}</small></td><td>${esc(t.customer)}<small>${esc(t.feature)}</small></td><td>${esc(t.policyName||t.policy)}<small>版本 ${esc(t.policy_revision??'—')} · ${esc(t.model||'尚无调用')}</small></td><td>${money(t.cost)} / ${money(t.budget)}<small>预留 ${money(t.reserved||0)}</small></td><td><span class="badge ${esc(t.status)}">${esc(labels[t.status]||t.status)}</span></td><td><button class="link" data-task-detail="${esc(t.id)}">查看 →</button></td></tr>`).join('')+(ts.length?'':'<tr><td class="empty" colspan="6">暂无匹配任务。接入工作流或编码工具后，任务会显示在这里。</td></tr>')+'</tbody></table></div>'}
function overview(d){return title('运行总览','所有统计来自当前服务的持久化记录。',refresh)+stats(d.metrics)+`<section class="card console-summary"><span>任务总数 <b>${Number(d.counts?.total||0)}</b></span><span>运行中 <b>${Number(d.counts?.running||0)}</b></span><span>待审批 <b>${Number(d.counts?.approval||0)}</b></span><span>风险事件 <b>${Number(d.riskCount||0)}</b></span><a class="link" href="#alerts">查看风险 →</a></section><section class="card"><div class="card-head"><h2>最近任务</h2><a class="link" href="#runs">全部任务 →</a></div>${taskTable(d.latestTasks||[])}</section><section class="card console-risk-preview"><div class="card-head"><h2>最近风险</h2></div>${(d.latestAlerts||[]).map(a=>`<div class="rule-row"><div><strong>${esc(a.title)}</strong><small>${esc(a.task_name||a.task_id)} · ${esc(a.detail)}</small></div><button class="link" data-task-detail="${esc(a.task_id)}">查看</button></div>`).join('')||'<div class="empty">尚无风险记录</div>'}</section>`}
function runs(d){return title('任务追踪','筛选、检查和管理服务端任务；新建任务只创建记录。',refresh+(session.canManage?'<button class="button primary" data-task-create>新建任务记录</button>':''))+`<form id="task-filters" class="console-filters"><label>搜索<input name="q" value="${esc(runFilters.q)}" placeholder="任务、客户、功能"></label><label>状态<select name="status"><option value="">全部状态</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${runFilters.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>客户<input name="customer" value="${esc(runFilters.customer)}" placeholder="精确客户名称"></label><label>功能<input name="feature" value="${esc(runFilters.feature)}" placeholder="精确功能名称"></label><button class="button primary">筛选</button><button class="button" type="button" data-task-reset>重置</button></form><section class="card">${taskTable(d.tasks||[])}</section>${pagination('task',d,runFilters.offset)}`}
function pagination(prefix,d,offset){const count=(d.tasks||d.alerts||[]).length;return `<div class="usage-pagination"><span>共 ${Number(d.total||0)} 条 · ${count?offset+1:0}–${offset+count}</span><button class="button" data-${prefix}-prev ${!offset?'disabled':''}>上一页</button><button class="button" data-${prefix}-next ${offset+count>=d.total?'disabled':''}>下一页</button></div>`}
function alerts(d){return title('风险与审批','审批与停止会写入真实服务和审计记录。',refresh)+`<div class="console-filters"><label>任务状态<select id="alert-status"><option value="">所有风险</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${alertFilters.status===k?'selected':''}>${v}</option>`).join('')}</select></label><span>同一任务的多条风险共享当前处理状态。</span></div><section class="card table-wrap"><table><thead><tr><th>触发时间 / 任务</th><th>风险与证据</th><th>处理 / 状态</th><th></th></tr></thead><tbody>${(d.alerts||[]).map(a=>`<tr><td>${esc(a.at)}<small>${esc(a.task_name||a.task_id)}</small></td><td><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></td><td>${esc(actions[a.action]||a.action)}<small>${esc(labels[a.status]||a.status)}</small></td><td>${a.status==='approval'&&session.canManage?`<button class="button primary" data-task-review="${esc(a.task_id)}">审批</button> `:''}<button class="link" data-task-detail="${esc(a.task_id)}">查看任务</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">暂无匹配风险记录</td></tr>'}</tbody></table></section>${pagination('alert',d,alertFilters.offset)}`}
function cost(d){return title('成本与业务结果','按客户、功能、模型核算已知费用，保留未计价提示。',refresh+'<button class="button" data-cost-export>导出分析</button>')+stats(d.summary)+`<section class="card table-wrap"><div class="card-head"><h2>客户 / 产品功能</h2></div><table><thead><tr><th>客户 / 功能</th><th>任务数</th><th>已知费用</th><th>成功 / 已结束</th><th>成功率</th><th>每次成功成本</th><th>未计价</th></tr></thead><tbody id="cost-groups">${(d.groups||[]).map(g=>`<tr><td>${esc(g.customer)}<small>${esc(g.feature)}</small></td><td>${Number(g.tasks)}</td><td>${money(g.cost)}</td><td>${Number(g.success)} / ${Number(g.completed)}</td><td>${g.completed?percent(g.rate):'—'}</td><td>${money(g.unit)}</td><td>${Number(g.unknown_cost||0)} 次</td></tr>`).join('')||'<tr><td colspan="7" class="empty">暂无任务成本</td></tr>'}</tbody></table></section><section class="card table-wrap console-risk-preview"><div class="card-head"><h2>模型用量</h2><a class="link" href="#usage">按时间查询明细 →</a></div><table><thead><tr><th>供应商 / 模型</th><th>调用数</th><th>输入 / 输出 Token</th><th>已知费用</th><th>成功率</th><th>每次成功成本</th><th>未计价</th></tr></thead><tbody id="cost-models">${(d.models||[]).map(m=>`<tr><td>${esc(m.provider)}<small>${esc(m.model)}</small></td><td>${Number(m.requests)}</td><td>${m.input_tokens==null?'—':Number(m.input_tokens)} / ${m.output_tokens==null?'—':Number(m.output_tokens)}</td><td>${money(m.cost)}</td><td>${m.completed?percent(m.rate):'—'}</td><td>${money(m.unit)}</td><td>${Number(m.unpriced_requests||0)} 次</td></tr>`).join('')||'<tr><td colspan="7" class="empty">暂无模型调用账本</td></tr>'}</tbody></table></section><p class="note">成功率按已结束任务计算。模型表只包含有模型账本的调用，未绑定模型的手工事件不会被分摊到模型。Token 汇总仅含已知数值，缺失部分不计入；“—”表示未知。未知价格需要补齐计费配置；已知费用只是当前可核算的部分。</p>`}
function policies(d){return title('费用策略','修改服务端预设，保存后用于新任务与新连接。已有任务保留创建时的策略快照。',refresh)+(!session.canManage?'<div class="note">当前为只读权限。使用 ADMIN_KEY 连接后可修改策略。</div>':'')+'<div class="cards3">'+(d.policies||[]).map(p=>`<form class="card policy" data-policy="${esc(p.id)}" data-revision="${Number(p.revision)}"><h2>${esc(p.name)}</h2><p data-policy-version>服务端版本 ${Number(p.revision)}</p>${[['budget','单任务预算（元）',.001],['loop','重复调用阈值（12 次窗口）',2],['retries','连续失败上限',1],['children','累计子智能体上限',1]].map(([k,l,min])=>`<label>${l}<input name="${k}" type="number" min="${min}" ${k==='loop'?'max="12"':''} step="${k==='budget'?'any':'1'}" value="${p[k]}" required ${!session.canManage?'disabled':''}></label>`).join('')}<label>触发后执行<select name="action" ${!session.canManage?'disabled':''}>${Object.entries(actions).map(([k,v])=>`<option value="${k}" ${p.action===k?'selected':''}>${v}</option>`).join('')}</select></label><button type="submit" class="button primary" ${!session.canManage?'disabled':''}>保存到服务端</button><div class="console-form-status" role="status"></div></form>`).join('')+'</div><p class="note">预算耗尽时，降级也不能继续消耗。编码工具不自动替换模型，其停止与审批能力取决于本机启动器；只监测连接仅告警。</p>'}
function bindPage(root,page,d,ticket){bindRefresh(root);root.querySelectorAll('[data-task-detail]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.taskDetail));root.querySelectorAll('[data-task-review]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.taskReview));if(page==='runs'){root.querySelector('#task-filters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);runFilters={...Object.fromEntries(['q','status','customer','feature'].map(k=>[k,String(f.get(k)||'').trim()])),offset:0};show()};root.querySelector('[data-task-reset]').onclick=()=>{runFilters={q:'',status:'',customer:'',feature:'',offset:0};show()};root.querySelector('[data-task-prev]').onclick=()=>{runFilters.offset=Math.max(0,runFilters.offset-50);show()};root.querySelector('[data-task-next]').onclick=()=>{runFilters.offset+=50;show()};root.querySelector('[data-task-create]')?.addEventListener('click',()=>createTask(ticket))}if(page==='alerts'){root.querySelector('#alert-status').onchange=e=>{alertFilters={status:e.target.value,offset:0};show()};root.querySelector('[data-alert-prev]').onclick=()=>{alertFilters.offset=Math.max(0,alertFilters.offset-50);show()};root.querySelector('[data-alert-next]').onclick=()=>{alertFilters.offset+=50;show()}}if(page==='cost')root.querySelector('[data-cost-export]').onclick=()=>download('agentguard-costs.json',JSON.stringify({exported_at:new Date().toISOString(),source:'server',...d},null,2));if(page==='policies')root.querySelectorAll('[data-policy]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button'),status=form.querySelector('[role=status]');if(!session?.canManage||b.disabled)return;b.disabled=true;status.textContent='正在保存…';try{const f=new FormData(form),body={revision:Number(form.dataset.revision),action:f.get('action'),...Object.fromEntries(['budget','loop','retries','children'].map(k=>[k,Number(f.get(k))]))};const p=await api('/api/policies/'+encodeURIComponent(form.dataset.policy),'PUT',body);if(ticket!==epoch||!form.isConnected)return;form.dataset.revision=p.revision;form.querySelector('[data-policy-version]').textContent='服务端版本 '+p.revision;status.textContent='已保存。仅用于后续创建的任务与连接。'}catch(err){if(ticket===epoch&&form.isConnected)status.textContent=err.message}finally{b.disabled=!session?.canManage}})}
function download(name,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function taskDetail(id){const ticket=epoch,detailTicket=++detailEpoch,dialog=openDialog('<h2>任务详情</h2><div id="task-detail" class="empty">正在读取…</div>'),box=dialog.querySelector('#task-detail');try{const d=await api('/api/tasks/'+encodeURIComponent(id));if(ticket!==epoch||detailTicket!==detailEpoch||!ownsDialog(box))return;const t=d.task,monitor=t.control==='monitor'||t.mode==='monitor'||t.source_mode==='monitor'||t.coding_mode==='monitor',managed=t.control==='managed'||t.mode==='managed'||t.source_mode==='managed'||t.coding_mode==='managed';box.className='';box.innerHTML=`<h2>${esc(t.name||t.id)}</h2><p>${esc(t.id)} · ${esc(t.customer)} / ${esc(t.feature)}</p><span class="badge ${esc(t.status)}">${esc(labels[t.status]||t.status)}</span><div class="budget-panel"><div><small>累计成本 / 预算</small><strong>${money(t.cost)} / ${money(t.budget)}</strong></div><div><small>已预留</small><strong>${money(t.reserved||0)}</strong></div><div><small>子智能体</small><strong>${(t.childIds||[]).length}</strong></div></div><p class="note">策略：${esc(t.policyName||t.policy)} · 版本 ${esc(t.policy_revision??'—')}。${t.historical?'历史导入任务仅用于查看，不会改变客户端或运行状态。':monitor?'此任务只监测，不能从控制台拦截客户端。':managed?'托管编码任务的停止由本机启动器执行；审批后需手动重新启动。':'停止将阻止后续代理调用；已经发出的请求仍需结算。'}</p>${(t.alerts||[]).map(a=>`<div class="note"><strong>${esc(a.title)}</strong> · ${esc(a.detail)}</div>`).join('')}${session.canManage&&!monitor&&!t.historical&&t.status==='approval'?'<form id="task-approval-form" class="console-filters"><label>追加预算（元）<input name="extraBudget" type="number" min="0.001" step="any" required></label><button class="button primary">批准并追加预算</button><button type="button" class="button" data-task-reject>拒绝并停止</button></form>':''}<div class="actions console-task-actions">${session.canManage&&!monitor&&!t.historical&&t.status==='running'?`<button class="button" data-task-stop="${esc(t.id)}">停止任务</button>${!managed?'<button class="button" data-task-finish="success">标记成功</button><button class="button" data-task-finish="failed">标记失败</button>':''}`:''}</div><div id="task-action-status" role="status"></div><h3>调用事件</h3><div class="trace-scroll">${(t.events||[]).map(e=>`<div class="event"><div><strong>${esc(e.tool||e.kind||'调用')} · ${esc(e.agent||'root')}</strong><small>${esc(e.at)}</small><p>${esc(JSON.stringify(e.input||{}))}${e.error?' · 调用失败':''}</p></div><span>${money(e.cost)}</span></div>`).join('')||'<p>尚无调用事件。</p>'}</div><h3>管理操作审计</h3><div class="trace-scroll">${(d.audit||[]).map(a=>`<div class="event"><div><strong>${esc(a.action)}</strong><small>${esc(a.at)} · ${esc(a.actor)}</small><p>${esc(JSON.stringify(a.after||{}))}</p></div></div>`).join('')||'<p>尚无管理操作。</p>'}</div>`;const form=box.querySelector('#task-approval-form');if(form){form.onsubmit=e=>{e.preventDefault();mutateTask(t.id,'approve',{approved:true,extraBudget:Number(new FormData(form).get('extraBudget'))},form,ticket)};form.querySelector('[data-task-reject]').onclick=()=>mutateTask(t.id,'approve',{approved:false},form,ticket)}box.querySelector('[data-task-stop]')?.addEventListener('click',()=>confirmTask(t.id,'stop',{},ticket));box.querySelectorAll('[data-task-finish]').forEach(b=>b.onclick=()=>confirmTask(t.id,'finish',{status:b.dataset.taskFinish},ticket))}catch(err){if(ticket===epoch&&detailTicket===detailEpoch&&ownsDialog(box))box.textContent=err.message}}
function confirmTask(id,action,body,ticket){const d=openDialog(`<h2>${action==='stop'?'停止任务':'确认任务结果'}</h2><p>${action==='stop'?'停止后将阻止此任务的后续代理调用；已经发出的调用仍需结算。':'请确认外部工作已结束。只有没有进行中调用的任务才能手动结束。'}</p><button class="button primary" id="task-confirm">确认${action==='stop'?'停止':body.status==='success'?'成功':'失败'}</button><div id="task-action-status" role="status"></div>`);d.querySelector('#task-confirm').onclick=()=>mutateTask(id,action,body,d.querySelector('#task-confirm'),ticket)}
async function mutateTask(id,action,body,control,ticket){const path='/api/tasks/'+encodeURIComponent(id)+'/'+action;if(!session?.canManage||pending.has(path))return;pending.add(path);const buttons=control.matches('button')?[control]:[...control.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const status=$('#task-action-status');try{await api(path,'POST',body);if(ticket!==epoch||!ownsDialog(control))return;closeDialog();show()}catch(err){if(ticket===epoch&&ownsDialog(status))status.textContent=err.message}finally{pending.delete(path);buttons.forEach(b=>b.disabled=false)}}
async function createTask(ticket){const dialog=openDialog('<h2>新建任务记录</h2><div id="task-create-content">正在读取策略…</div>'),box=dialog.querySelector('#task-create-content');try{const d=await api('/api/policies');if(ticket!==epoch||!ownsDialog(box))return;box.innerHTML=`<p>只创建预算与追踪记录，不启动模型调用。外部工作流使用同一任务 ID 上报事件或发起代理请求。</p><form id="task-create-form" class="policy"><label>任务 ID<input name="id" required pattern="[a-zA-Z0-9_-]{1,80}" maxlength="80" placeholder="run-001"></label><label>任务名称<input name="name" maxlength="100"></label><label>客户<input name="customer" maxlength="100"></label><label>产品功能<input name="feature" maxlength="100"></label><label>费用策略<select name="policy">${d.policies.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${money(p.budget)} · v${p.revision}</option>`).join('')}</select></label><button class="button primary">创建记录</button><div role="status"></div></form>`;const form=box.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button'),status=form.querySelector('[role=status]');if(!session?.canManage||pending.has('/api/tasks')||b.disabled)return;b.disabled=true;pending.add('/api/tasks');try{const f=new FormData(form);await api('/api/tasks','POST',Object.fromEntries(['id','name','customer','feature','policy'].map(k=>[k,String(f.get(k)||'').trim()])));if(ticket!==epoch||!ownsDialog(form))return;closeDialog();runFilters.offset=0;show()}catch(err){if(ticket===epoch&&ownsDialog(form))status.textContent=err.message}finally{pending.delete('/api/tasks');b.disabled=false}}}catch(err){if(ticket===epoch&&ownsDialog(box))box.textContent=err.message}}
function deployment(){return title('本机联调，再部署','先验证本机真实服务和持久化数据，再迁移到服务器。')+'<div class="grid"><section class="card policy"><h2>启动本机服务</h2><p>使用 Node.js 20.19，在源码目录执行：</p><pre>npm ci\nnpm run setup:local\nnpm run doctor\nnpm run start:local</pre><p>打开终端显示的本机地址，用本机配置中的 ADMIN_KEY 连接。数据库和供应商密钥留在本机，首次启动没有样例业务数据。</p><a class="button" href="DEPLOY.html" target="_blank" rel="noopener">部署说明 ↗</a> <a class="button" href="CODING.html" target="_blank" rel="noopener">Claude / Codex 接入 ↗</a></section><section class="card policy"><h2>按实际链路验收</h2><p>在接入中心配置模型和单价，再让一个小任务经过模型代理；检查任务事件、用量账本与风险处理。服务启动后可在另一个终端执行 npm run smoke:local 验证本机无外部调用的链路。Claude / Codex 需要配置遥测，受控停止还需要本机启动器。</p><p class="note">本页连接状态只代表 AgentGuard 服务可用，不代表供应商、告警机器人或本机 CLI 已完成联调。</p><a class="button" href="agentguard-source.tar.gz" download>下载源码</a> <a class="button" href="demo.html" target="_blank" rel="noopener">打开独立演练 ↗</a></section></div>'}
window.addEventListener('hashchange',()=>{detailEpoch++;closeDialog();show()});document.querySelector('.skip-link').onclick=e=>{e.preventDefault();$('#app').focus()};show();
